using Microsoft.EntityFrameworkCore;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;

var builder=WebApplication.CreateBuilder(args);builder.Logging.AddJsonConsole();
builder.Services.AddDbContext<DashboardDb>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("Dashboard")??Environment.GetEnvironmentVariable("DASHBOARD_DB")??throw new InvalidOperationException("Configure the service SQL Server connection string.")));
builder.Services.AddDbContext<AuditReadDb>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("AuditRead")??Environment.GetEnvironmentVariable("AUDIT_DB")??throw new InvalidOperationException("Configure the audit database read connection string.")));
builder.Services.AddHealthChecks();builder.Services.AddCors(o=>o.AddDefaultPolicy(p=>p.WithOrigins((builder.Configuration["Cors:AllowedOrigins"]??"http://localhost:5173,http://localhost:8080").Split(',',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries)).AllowAnyHeader().AllowAnyMethod().AllowCredentials()));builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen();builder.Services.AddSignalR();builder.Services.AddHostedService<Worker>();
var app=builder.Build();app.Use(async(c,n)=>{var id=c.Request.Headers["X-Correlation-ID"].FirstOrDefault();if(string.IsNullOrWhiteSpace(id))id=Guid.NewGuid().ToString("N");c.TraceIdentifier=id;c.Response.Headers["X-Correlation-ID"]=id;await n();});app.UseCors();app.UseSwagger();app.UseSwaggerUI();app.MapHealthChecks("/health");app.MapGet("/health/live",()=>Results.Ok(new{status="live"}));app.MapGet("/health/ready",async(DashboardDb db,CancellationToken ct)=>await db.Database.CanConnectAsync(ct)?Results.Ok(new{status="ready"}):Results.StatusCode(503));
app.MapGet("/dashboard/overview",async(DashboardDb db,CancellationToken ct)=>{var rows=await db.Events.AsNoTracking().ToListAsync(ct);var registered=rows.Sum(x=>x.Registered);var checkedIn=rows.Sum(x=>x.CheckedIn);var participants=await db.Registrations.AsNoTracking().Where(x=>x.Status!="Cancelled").Select(x=>x.ParticipantId).Distinct().CountAsync(ct);return Results.Ok(new{totalEvents=rows.Count,totalRegistrations=registered,totalParticipants=participants,totalCheckedIn=checkedIn,totalCancelled=rows.Sum(x=>x.Cancelled),totalAvailableSeats=rows.Sum(x=>Math.Max(0,x.Capacity-x.Registered)),checkInRate=registered==0?0:Math.Round(100d*checkedIn/registered,1)});});
app.MapGet("/dashboard/top-events",async(DashboardDb db,int limit=5,CancellationToken ct=default)=>Results.Ok(await db.Events.AsNoTracking().OrderByDescending(x=>x.Registered).ThenBy(x=>x.EventName).Take(Math.Clamp(limit,1,20)).ToListAsync(ct)));
app.MapGet("/dashboard/chart",async(DashboardDb db,DateTimeOffset? from,DateTimeOffset? to,CancellationToken ct)=>{var q=db.Activities.AsNoTracking().AsQueryable();if(from.HasValue)q=q.Where(x=>x.OccurredAt>=from);if(to.HasValue)q=q.Where(x=>x.OccurredAt<to);return Results.Ok(await q.GroupBy(x=>x.OccurredAt.Date).Select(g=>new{date=g.Key,registrations=g.Count(x=>x.EventType=="ParticipantRegistered"),checkIns=g.Count(x=>x.EventType=="ParticipantCheckedIn"),cancelled=g.Count(x=>x.EventType=="ParticipantCancelled")}).OrderBy(x=>x.date).ToListAsync(ct));});
app.MapGet("/dashboard/report",async(DashboardDb db,Guid? eventId,DateTime? from,DateTime? to,CancellationToken ct)=>{var q=db.Activities.AsNoTracking().Where(x=>x.EventType=="ParticipantRegistered"||x.EventType=="ParticipantCheckedIn"||x.EventType=="ParticipantCancelled");if(eventId.HasValue)q=q.Where(x=>x.EventId==eventId);if(from.HasValue)q=q.Where(x=>x.OccurredAt.Date>=from.Value.Date);if(to.HasValue)q=q.Where(x=>x.OccurredAt.Date<=to.Value.Date);var registrations=await q.CountAsync(x=>x.EventType=="ParticipantRegistered",ct);var checkIns=await q.CountAsync(x=>x.EventType=="ParticipantCheckedIn",ct);var cancelled=await q.CountAsync(x=>x.EventType=="ParticipantCancelled",ct);var chart=await q.GroupBy(x=>x.OccurredAt.Date).Select(g=>new{date=g.Key,registrations=g.Count(x=>x.EventType=="ParticipantRegistered"),checkIns=g.Count(x=>x.EventType=="ParticipantCheckedIn"),cancelled=g.Count(x=>x.EventType=="ParticipantCancelled")}).OrderBy(x=>x.date).ToListAsync(ct);var active=registrations-cancelled;return Results.Ok(new{totalRegistrations=registrations,totalCheckedIn=checkIns,totalCancelled=cancelled,checkInRate=active==0?0:Math.Round(100d*checkIns/active,1),chart});});
app.MapGet("/dashboard/events/{eventId:guid}",async(Guid eventId,DashboardDb db,CancellationToken ct)=>await db.Events.AsNoTracking().FirstOrDefaultAsync(x=>x.EventId==eventId,ct) is{} e?Results.Ok(e):Results.NotFound());
app.MapGet("/dashboard/events/{eventId:guid}/statistics",async(Guid eventId,DashboardDb db,CancellationToken ct)=>await db.Events.AsNoTracking().FirstOrDefaultAsync(x=>x.EventId==eventId,ct) is{} e?Results.Ok(new{e.EventId,e.EventName,e.Capacity,e.Registered,e.Cancelled,e.CheckedIn,attendanceRate=e.Registered==0?0:Math.Round(100d*e.CheckedIn/e.Registered,1)}):Results.NotFound());
app.MapGet("/dashboard/events/{eventId:guid}/chart",async(Guid eventId,DashboardDb db,CancellationToken ct)=>Results.Ok(await db.Activities.AsNoTracking().Where(x=>x.EventId==eventId).GroupBy(x=>x.OccurredAt.Date).Select(g=>new{date=g.Key,registrations=g.Count(x=>x.EventType=="ParticipantRegistered"),checkIns=g.Count(x=>x.EventType=="ParticipantCheckedIn")}).OrderBy(x=>x.date).ToListAsync(ct)));
app.MapGet("/dashboard/recent-activities",async(DashboardDb db,int page=1,int pageSize=20,CancellationToken ct=default)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Activities.AsNoTracking().OrderByDescending(x=>x.OccurredAt);var total=await q.CountAsync(ct);return Results.Ok(new{items=await q.Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct),page,pageSize,total});});
app.MapGet("/admin/audit-logs",async(AuditReadDb db,string? search,int page=1,int pageSize=20,CancellationToken ct=default)=>{page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);if(!await db.Database.CanConnectAsync(ct))return Results.StatusCode(503);var q=db.Entries.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>(x.ParticipantName??"").Contains(search)||(x.Email??"").Contains(search)||x.Description.Contains(search)||x.EventType.Contains(search)||(x.RegistrationCode??"").Contains(search));var total=await q.CountAsync(ct);return Results.Ok(new{items=await q.OrderByDescending(x=>x.CreatedAt).Skip((page-1)*pageSize).Take(pageSize).ToListAsync(ct),page,pageSize,total});});
app.MapHub<DashboardHub>("/hubs/dashboard");app.Run();

public sealed class DashboardHub:Microsoft.AspNetCore.SignalR.Hub{}
public sealed class DashboardEvent{public Guid EventId{get;set;}public string EventName{get;set;}="";public int Capacity{get;set;}public int Registered{get;set;}public int Cancelled{get;set;}public int CheckedIn{get;set;}public int Version{get;set;}public bool IsDeleted{get;set;}public DateTimeOffset UpdatedAt{get;set;}}
public sealed class DashboardActivity{public long Id{get;set;}public Guid MessageId{get;set;}public Guid EventId{get;set;}public string EventType{get;set;}="";public string EventName{get;set;}="";public string RegistrationCode{get;set;}="";public string? ParticipantName{get;set;}public Guid? ParticipantId{get;set;}public DateTimeOffset OccurredAt{get;set;}public string CorrelationId{get;set;}="";}
public sealed class DashboardProcessed{public long Id{get;set;}public Guid EventId{get;set;}public DateTimeOffset ProcessedAt{get;set;}}
public sealed class DashboardRegistration{public Guid RegistrationId{get;set;}public Guid ParticipantId{get;set;}public string Status{get;set;}="";public int Version{get;set;}}
public sealed class AuditReadLog{public long Id{get;set;}public Guid MessageId{get;set;}public Guid EventId{get;set;}public string EventType{get;set;}="";public Guid? ParticipantId{get;set;}public string? ParticipantName{get;set;}public string? Email{get;set;}public Guid? RegistrationId{get;set;}public string? RegistrationCode{get;set;}public string Description{get;set;}="";public DateTimeOffset CreatedAt{get;set;}public string CorrelationId{get;set;}="";public string Payload{get;set;}="";}
public sealed class AuditReadDb(DbContextOptions<AuditReadDb> o):DbContext(o){public DbSet<AuditReadLog> Entries=>Set<AuditReadLog>();protected override void OnModelCreating(ModelBuilder b){b.Entity<AuditReadLog>().ToTable("AuditLogs").HasKey(x=>x.Id);}}
public sealed class DashboardDb(DbContextOptions<DashboardDb> o):DbContext(o){public DbSet<DashboardEvent> Events=>Set<DashboardEvent>();public DbSet<DashboardActivity> Activities=>Set<DashboardActivity>();public DbSet<DashboardProcessed> Processed=>Set<DashboardProcessed>();public DbSet<DashboardRegistration> Registrations=>Set<DashboardRegistration>();protected override void OnModelCreating(ModelBuilder b){b.Entity<DashboardEvent>().ToTable("DashboardStatistics").HasKey(x=>x.EventId);b.Entity<DashboardEvent>().HasQueryFilter(x=>!x.IsDeleted);b.Entity<DashboardActivity>().ToTable("DashboardActivities");b.Entity<DashboardActivity>().HasIndex(x=>x.MessageId).IsUnique();b.Entity<DashboardProcessed>().ToTable("ProcessedMessages");b.Entity<DashboardProcessed>().HasIndex(x=>x.EventId).IsUnique();b.Entity<DashboardRegistration>().ToTable("DashboardRegistrations").HasKey(x=>x.RegistrationId);}}
